mapper.select:
select bsr.id, bsr.sensitive_txt,bsr.sensitive_name,bsr.classification_id,bsr.record_add_time,bsr.user_id,bsr.user_name,bsr.user_type,bsc.classification_name
from hou_base_sensitive_record bsr
LEFT JOIN hou_base_sensitive_classification bsc on bsr.classification_id = bsc.classification_id
where 1 = 1

    and bsr.sensitive_name like CONCAT('%',#{param.sensitiveName},'%')


    and bsr.classification_id = #{param.classificationId}


    and bsr.record_add_time >= #{param.recordStartTime}


    and bsr.record_add_time <= #{param.recordEndTime}


    and bsr.user_name = #{param.userName}


    and  bsr.user_type = #{param.userType}

 order by bsr.record_add_time desc
